test('Sword hits draw a slash and push a surviving enemy away from the player',()=>{
 const h=boot(),q=h.qa;q.start();q.mobs([[0,-2.5]]);const m=q.monsters()[0];Object.assign(m,{kind:'charger',health:42,maxHealth:42,windup:.5,chargeTime:.4});q.attack();assert.equal(m.health,18);assert.equal(q.impacts()[0].type,'slash');assert.equal(m.windup,0);assert.equal(m.chargeTime,0);const normalSize=q.effectMesh().length;assert(normalSize>200);q.updateImpactEffects(.12);assert(m.z<-2.9);q.render();
 const charged=boot(),c=charged.qa;c.start();c.mobs([[0,-2.5]]);Object.assign(c.monsters()[0],{health:120,maxHealth:120});c.attack(true);assert.equal(c.impacts().length,0);assert.equal(c.monsters()[0].health,120);c.attack();assert.equal(c.monsters()[0].health,83);assert.equal(c.impacts()[0].demonic,true);assert.equal(c.effectMesh().length,normalSize);
});
test('Blaster flames attach to the shot impact and follow the enemy position and rotation',()=>{
 const h=boot(),q=h.qa;q.avatar(1);q.start();q.mobs([[0,-10]]);const m=q.monsters()[0];Object.assign(m,{kind:'thrower',health:34,maxHealth:34});q.attack();assert.equal(q.impacts().length,0);for(let i=0;i<15;i++)q.updateWeapons(.04);assert.equal(m.health,16);const effect=q.impacts()[0];assert.equal(effect.type,'fire');assert(Math.hypot(effect.localX,effect.localZ)>.3);assert(effect.localY>.8&&effect.localY<1.5);assert(!m.recoil);m.x+=3;m.z+=2;m.yaw=Math.PI/2;const mesh=q.effectMesh();assert(Math.abs(mesh[0]-(m.x+effect.localZ+Math.sin(effect.seed)*.23))<.0001);assert(Math.abs(mesh[2]-(m.z-effect.localX+Math.cos(effect.seed)*.20))<.0001);assert(mesh.every(Number.isFinite));q.updateWeapons(1);assert.equal(m.health,16);q.render();
});
test('Hammer area hits push each affected enemy outward and surround them with electricity',()=>{
 const h=boot(),q=h.qa;q.avatar(2);q.start();q.mobs([[0,-2.5],[1,-2.7],[12,0]]);const mobs=q.monsters();for(const m of mobs)Object.assign(m,{health:100,maxHealth:100});q.attack();const impact=q.get().pending,distances=mobs.map(m=>Math.hypot(m.x-impact.x,m.z-impact.z));q.updateWeapons(.28);assert.equal(q.impacts().length,2);assert(q.impacts().every(e=>e.type==='electric'));for(let i=0;i<2;i++){assert.equal(mobs[i].health,68);assert(Math.hypot(mobs[i].x-impact.x,mobs[i].z-impact.z)>distances[i]+.6);}assert.equal(mobs[2].health,100);const mesh=q.effectMesh();assert(mesh.length>400&&mesh.every(Number.isFinite));q.render();
});
test('Enemy knockback respects fort walls and the island shore',()=>{
 const h=boot(),q=h.qa;q.start();const f=q.get().forts[0];q.mobs([[f.x-23.5,f.z]]);let m=q.monsters()[0];Object.assign(m,{health:100,maxHealth:100});q.hitTarget(m,1,{weapon:'sword',sourceX:f.x-26,sourceZ:f.z});q.updateImpactEffects(.3);assert(m.x<=f.x-23.2);const edge={x:0,z:0};q.moveBody(edge,500,0,.55);q.mobs([[edge.x,edge.z]]);m=q.monsters()[0];Object.assign(m,{health:100,maxHealth:100});q.hitTarget(m,1,{weapon:'hammer',sourceX:edge.x-2,sourceZ:edge.z,charged:true});q.updateImpactEffects(.3);assert(q.onIsland(m.x,m.z,.55));
});
test('Impact effects and recoil freeze on pause and clear when entering the cave',()=>{
 const h=boot(),q=h.qa;q.start();q.mobs([[0,-2.5]]);const m=q.monsters()[0];Object.assign(m,{health:100,maxHealth:100});q.attack();const before=q.impacts()[0],z=m.z,time=m.recoil.time,mesh=q.effectMesh();q.pause();q.update(2);q.updateWeapons(2);q.updateImpactEffects(2);assert.equal(m.z,z);assert.equal(m.recoil.time,time);assert.equal(q.impacts()[0].life,before.life);assert.deepEqual(q.effectMesh(),mesh);q.resume();q.updateImpactEffects(.04);assert(m.z<z);q.enterCave();assert.equal(q.impacts().length,0);assert.equal(m.recoil,null);q.render();
});
test('Lethal hits keep a short defeat animation and respawning clears every impact',()=>{
 const h=boot(),q=h.qa;q.start();q.mobs([[0,-2.5]]);const m=q.monsters()[0];q.attack();assert.equal(m.alive,false);assert(m.defeatVisual>0);assert.equal(q.get().score,10);q.render();m.respawnTimer=.01;q.set({x:30,z:30});q.updateMonsters(.02);assert.equal(m.alive,true);assert.equal(m.defeatVisual,0);assert.equal(m.recoil,null);assert.equal(q.impacts().length,0);assert.equal(q.get().experience,10);
});
test('The golem receives impact effects with reduced recoil and keeps its announced attack',()=>{
 const h=boot(),q=h.qa;q.start();q.enterCave();q.bossSet({x:0,z:0,action:'slam',timer:1});const boss=q.get().boss;q.set({x:0,z:4,yaw:Math.PI});q.attack();q.updateImpactEffects(.21);const after=q.get().boss;assert.equal(after.action,'slam');assert.equal(after.timer,1);assert.equal(after.health,936);assert(Math.abs(after.z-boss.z)>.1&&Math.abs(after.z-boss.z)<.35);assert(q.effectMesh().every(Number.isFinite));q.render();
});
test('Camera avoids the spawn arch and remains finite when jumping below it',()=>{const h=boot(),q=h.qa;q.start();q.render();const eye=q.get().camera;assert(q.cameraSolids.every(b=>{const t=q.segmentBox([0,1.4,0],eye,b);return t===null||t<.00001||t>=1;}),'Camera view crosses scenery');q.set({x:0,z:3.5,y:1.5});q.render();});
test('A fort corner blocks enemy damage',()=>{const h=boot(),q=h.qa;q.start();const f=q.get().forts[0],x=f.x+3.5,z=f.z+20;q.set({x,z,health:100,invulnerable:0});q.mobs([[f.x+4.4,f.z+21.4]]);assert(q.blocked(x,z,f.x+4.4,f.z+21.4));q.update(1/60);assert.equal(q.get().health,100);});
test('Monster hits jolt and push the avatar away without crossing walls or shore',()=>{const h=boot(),q=h.qa;q.start();q.mobs([[-1.5,0]]);q.set({x:0,z:0,health:100,invulnerable:0});q.update(1/60);assert.equal(q.get().health,88);assert(q.get().player.hitJolt>0);q.mobs([]);for(let i=0;i<12;i++)q.update(1/60);assert(q.get().player.x>.65&&q.get().player.x<1.4);const f=q.get().forts[0];q.set({x:f.x-23.25,z:f.z,y:0,vy:0,invulnerable:0});q.damage(12,{x:f.x-24.5,z:f.z});for(let i=0;i<12;i++)q.update(1/60);assert(q.get().player.x<=f.x-23.2);const edge={x:0,z:0};q.moveBody(edge,500,0,.42);q.set({x:edge.x,z:edge.z,y:0,vy:0,invulnerable:0});q.damage(12,{x:edge.x-1,z:edge.z});for(let i=0;i<12;i++)q.update(1/60);assert(q.onIsland(q.get().player.x,q.get().player.z,.42));});
test('The island spawns pursuers, chargers and throwers with distinct silhouettes',()=>{const h=boot(),q=h.qa;q.start();const types=new Set(q.monsters().map(m=>m.kind));assert.deepEqual([...types].sort(),['charger','chaser','thrower']);assert(q.monsters().every(m=>m.alive&&m.color.every(Number.isFinite)));q.render();});
test('Chargers warn, commit to a direction, and can be dodged',()=>{const h=boot(),q=h.qa;q.start();q.mobs([[0,-7]]);let m=q.monsters()[0];Object.assign(m,{kind:'charger',windup:0,chargeTime:0,chargeCooldown:0,chargeX:0,chargeZ:0});q.set({x:0,z:0,y:0,health:100,invulnerable:0});q.updateMonsters(.04);assert(m.windup>.6);assert.equal(m.z,-7);q.updateMonsters(.7);assert(m.chargeTime>0);q.set({x:4,z:0});q.updateMonsters(.3);q.updateMonsters(.35);assert.equal(q.get().health,100);q.mobs([[0,-7]]);m=q.monsters()[0];Object.assign(m,{kind:'charger',windup:0,chargeTime:0,chargeCooldown:0,chargeX:0,chargeZ:0});q.set({x:0,z:0,health:100,invulnerable:0});q.updateMonsters(.04);q.updateMonsters(.7);q.updateMonsters(.5);assert.equal(q.get().health,84);});
