test('Enemy shots freeze on pause and clear before the boss fight',()=>{const h=boot(),q=h.qa;q.start();q.mobs([[0,-10]]);Object.assign(q.monsters()[0],{kind:'thrower',attack:0,speed:0});q.set({x:0,z:0,y:0});q.updateMonsters(.04);assert.equal(q.enemyBolts().length,1);q.pause();const before={...q.enemyBolts()[0]};q.update(1);assert.equal(q.enemyBolts()[0].z,before.z);q.resume();q.enterCave();assert.equal(q.enemyBolts().length,0);});
